/*==========================================================================*/

//--------------------------------------------------------------------------//
//! \desc Computes a 16-bit CCITT CRC calculation of an arbitrary memory
//!       block with arbitrary block size.

//! \assume -none-

//! \notes  Uses $FFFF as the initial CRC value.

//! \param  mem : Starting address of block.
//! \param  size : Block size in bytes.

//! \return \b UInt16 : The computed CRC

//! \throws -none-

//--------------------------------------------------------------------------//

UInt16 nvram_calc_crc (void const * mem , UInt16 size)
{
  UInt16 crc = 0xFFFF ;

  while (size--)
    {
      crc_calc_ccitt (& crc , * (const UInt8 *) mem) ;

      mem = (const UInt8 *) mem + 1 ;
    }

  return crc ;
}

